import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import ApplicantForm from './ApplicantForm';
import ApplicantDashboard from './ApplicantDashboard';
import Chatbot from './Chatbot';
import RecruiterDashboard from './RecruiterDashboard';
import { Login, Register } from './AuthForms';

function PrivateRoute({ children, token, role, allowedRoles }) {
  if (!token) return <Navigate to="/login" />;
  if (allowedRoles && !allowedRoles.includes(role)) return <Navigate to="/" />;
  return children;
}

function App() {
  const [token, setToken] = useState(localStorage.getItem('token'));
  const [role, setRole] = useState(localStorage.getItem('role'));
  const [applicantId, setApplicantId] = useState(null);
  const [showRegister, setShowRegister] = useState(false);

  const handleLogin = (jwt, userRole) => {
    setToken(jwt);
    setRole(userRole);
    localStorage.setItem('token', jwt);
    localStorage.setItem('role', userRole);
  };

  const handleLogout = () => {
    setToken(null);
    setRole(null);
    setApplicantId(null);
    localStorage.removeItem('token');
    localStorage.removeItem('role');
  };

  return (
    <Router>
      <div className="app-container">
        <h1>QualifyAI</h1>
        {token && <button onClick={handleLogout} style={{ float: 'right' }}>Logout</button>}
        <Routes>
          <Route path="/login" element={
            showRegister ? (
              <>
                <Register onRegister={() => setShowRegister(false)} />
                <button onClick={() => setShowRegister(false)} style={{ marginTop: 8 }}>
                  Back to Login
                </button>
              </>
            ) : (
              <>
                <Login onLogin={handleLogin} />
                <button onClick={() => setShowRegister(true)} style={{ marginTop: 8 }}>
                  Register
                </button>
              </>
            )
          } />
          <Route path="/recruiter" element={
            <PrivateRoute token={token} role={role} allowedRoles={['recruiter']}>
              <RecruiterDashboard token={token} />
            </PrivateRoute>
          } />
          <Route path="/applicant" element={
            <PrivateRoute token={token} role={role} allowedRoles={['applicant']}>
              {!applicantId ? (
                <ApplicantForm onSubmitted={setApplicantId} token={token} />
              ) : (
                <>
                  <ApplicantDashboard applicantId={applicantId} token={token} />
                  <Chatbot applicantId={applicantId} token={token} />
                </>
              )}
            </PrivateRoute>
          } />
          <Route path="/" element={
            token ? (
              role === 'recruiter' ? <Navigate to="/recruiter" /> : <Navigate to="/applicant" />
            ) : <Navigate to="/login" />
          } />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
